using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class VerifyAttack01Tail{
 public static object Run(){var live=GameObject.Find("Attack 01 - Attack");var root=UnityEngine.Object.Instantiate(live);root.transform.SetPositionAndRotation(new Vector3(1000,0,1000),Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;var clip=a.runtimeAnimatorController.animationClips[0];var source=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/3DBattle/NewPlayer/Attack/Previews/BeforeAttack01TailFit_20261103/NewKnight_Attack_Preview.anim");var sword=root.GetComponentsInChildren<Transform>().First(t=>t.name=="Sword");var skin=root.GetComponentInChildren<SkinnedMeshRenderer>();float directionError=0,frontError=0;var p=sword.localPosition;float mountDrift=0;
 var camGo=new GameObject("Tail verification camera");var cam=camGo.AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.25f,.27f,.29f);cam.fieldOfView=38;var rt=new RenderTexture(360,520,24);cam.targetTexture=rt;var tex=new Texture2D(1440,520,TextureFormat.RGB24,false);var previous=RenderTexture.active;
 try{for(int f=0;f<=168;f++){float time=f/60f;source.SampleAnimation(a.gameObject,time);var q=sword.rotation;var bp=skin.bones.Select(b=>b.position).ToArray();clip.SampleAnimation(a.gameObject,time);directionError=Mathf.Max(directionError,Quaternion.Angle(q,sword.rotation));mountDrift=Mathf.Max(mountDrift,Vector3.Distance(p,sword.localPosition));if(f<=102)for(int b=0;b<bp.Length;b++)frontError=Mathf.Max(frontError,Vector3.Distance(bp[b],skin.bones[b].position));}
 int[] frames={51,60,72,84};for(int i=0;i<4;i++){clip.SampleAnimation(a.gameObject,frames[i]/30f);var target=skin.bones.First(b=>b.name=="Hips").position+Vector3.up*.15f;cam.transform.position=target+new Vector3(-2.3f,1.3f,4.3f);cam.transform.LookAt(target);cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,360,520),i*360,0);}tex.Apply();System.IO.File.WriteAllBytes("Assets/3DBattle/Authoring~/Attack01TailVerified.png",tex.EncodeToPNG());return new{directionError,frontBodyPositionError=frontError,mountDrift,swordCurveKeys=AnimationUtility.GetCurveBindings(clip).Where(b=>b.path.EndsWith("Sword")).Select(b=>AnimationUtility.GetEditorCurve(clip,b).length).ToArray()};}
 finally{RenderTexture.active=previous;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(camGo);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
